class RateGate:
    def __init__(self, per_chat: float = 0.15):
        self.per_chat = per_chat
        self.last: Dict[int, float] = {}
        self.lock = asyncio.Lock()

    async def wait(self, key: int) -> None:
        async with self.lock:
            now = time.monotonic()
            remaining = self.per_chat - (now - self.last.get(key, 0.0))
            if remaining > 0:
                await asyncio.sleep(remaining)
            self.last[key] = time.monotonic()


SEND_GATE = RateGate()


class TaskRegistry:
    def __init__(self) -> None:
        self.tasks: Dict[str, asyncio.Task] = {}
        self.meta: Dict[str, Dict[str, Any]] = {}
        self.lock = asyncio.Lock()

    async def add(self, key: str, coro: Awaitable[Any], **meta: Any) -> asyncio.Task:
        async with self.lock:
            old = self.tasks.get(key)
            if old and not old.done():
                old.cancel()
            task = asyncio.create_task(coro, name=key)
            self.tasks[key] = task
            self.meta[key] = meta
            task.add_done_callback(lambda _: self.tasks.pop(key, None))
            return task

    async def cancel(self, key: str) -> bool:
        async with self.lock:
            task = self.tasks.pop(key, None)
            self.meta.pop(key, None)
            if task and not task.done():
                task.cancel()
                return True
        return False

    async def cancel_prefix(self, prefix: str) -> int:
        async with self.lock:
            keys = [k for k in self.tasks if k.startswith(prefix)]
        count = 0
        for key in keys:
            if await self.cancel(key):
                count += 1
        return count

    def snapshot(self) -> List[Dict[str, Any]]:
        return [
            {'key': k, 'done': t.done(), **self.meta.get(k, {})}
            for k, t in self.tasks.items()
        ]


TASKS = TaskRegistry()


class EntityResolver:
    def __init__(self, client: Any):
        self.client = client
        self.cache: Dict[str, Tuple[float, Any]] = {}
        self.ttl = 120.0

    async def resolve(self, value: Any, event: Any = None) -> Any:
        if value is None or value == '':
            if event is not None and getattr(event, 'is_reply', False):
                replied = await event.get_reply_message()
                if replied and replied.sender_id:
                    return await self.client.get_entity(replied.sender_id)
            raise ValueError('Target missing')
        if isinstance(value, (int,)):
            return await self.client.get_entity(value)
        text = str(value).strip()
        aliases = {
            'self': 'me', 'myself': 'me', 'khud': 'me', 'mujhe': 'me',
            'him': value, 'her': value,
        }
        text = aliases.get(text.lower(), text)
        if text.isdigit() or (text.startswith('-') and text[1:].isdigit()):
            return await self.client.get_entity(int(text))
        if text.startswith('@'):
            text = text[1:]
        key = text.casefold()
        cached = self.cache.get(key)
        if cached and time.monotonic() - cached[0] < self.ttl:
            return cached[1]
        entity = await self.client.get_entity(text)
        self.cache[key] = (time.monotonic(), entity)
        return entity


class PermissionGate:
    def __init__(self, client: Any, owner_id: int):
        self.client = client
        self.owner_id = int(owner_id)

    async def is_owner(self, sender_id: Optional[int]) -> bool:
        return bool(sender_id and int(sender_id) == self.owner_id)

    async def is_controller(self, sender_id: Optional[int]) -> bool:
        if await self.is_owner(sender_id):
            return True
        return int(sender_id or 0) in {int(x) for x in STATE.value.get('sudo', [])}

    async def can_manage_chat(self, chat_id: int, sender_id: Optional[int]) -> bool:
        if await self.is_controller(sender_id):
            return True
        if not sender_id:
            return False
        try:
            p = await self.client.get_permissions(chat_id, sender_id)
            return bool(getattr(p, 'is_admin', False) or getattr(p, 'is_creator', False))
        except Exception:
            return False


class SafeWorkspace:
    ALLOWED_EXT = {
        '.py', '.pyw', '.js', '.jsx', '.ts', '.tsx', '.json', '.yaml', '.yml',
        '.toml', '.ini', '.cfg', '.txt', '.md', '.html', '.css', '.xml', '.env.example',
    }
    SKIP = {'.git', '.venv', 'venv', 'node_modules', '__pycache__', '.lervex_backups', '.lervex_state'}
    SECRET_NAME = re.compile(r'(?i)(^|/)(\.env(?:\..*)?|.*secret.*|.*password.*|.*credential.*|.*\.session|.*\.(?:pem|key|p12))$')
    DANGEROUS = re.compile(
        r'(?i)(?:os\.system\s*\(|subprocess\.(?:run|Popen|call|check_call)\s*\(|\beval\s*\(|\bexec\s*\(|\brm\s+-rf\b|curl\s+[^\n|]+\|\s*(?:sh|bash)|wget\s+[^\n|]+\|\s*(?:sh|bash))'
    )

    def __init__(self, root: Path):
        self.root = root.resolve()

    def rel(self, path: Union[str, Path]) -> str:
        p = (self.root / path).resolve() if not Path(path).is_absolute() else Path(path).resolve()
        if os.path.commonpath([str(self.root), str(p)]) != str(self.root):
            raise ValueError('Path escapes workspace')
        return str(p.relative_to(self.root)).replace(os.sep, '/')

    def allowed(self, rel_path: str) -> bool:
        rel = str(rel_path).replace('\\', '/').lstrip('./')
        if not rel or self.SECRET_NAME.search(rel):
            return False
        parts = rel.split('/')
        if any(x in self.SKIP for x in parts):
            return False
        if rel.endswith('.env.example'):
            return True
        return Path(rel).suffix.lower() in self.ALLOWED_EXT

    def project_map(self, limit: int = 2500) -> List[str]:
        items: List[str] = []
        for p in self.root.rglob('*'):
            try:
                if not p.is_file():
                    continue
                rel = self.rel(p)
                if self.allowed(rel):
                    items.append(rel)
                    if len(items) >= limit:
                        break
            except Exception:
                continue
        return sorted(items)

    def scan(self, rel_path: str) -> Dict[str, Any]:
        rel = self.rel(rel_path)
        if not self.allowed(rel):
            raise ValueError('File is protected or unsupported')
        p = self.root / rel
        source = p.read_text(encoding='utf-8', errors='replace')
        result: Dict[str, Any] = {
            'path': rel,
            'bytes': p.stat().st_size,
            'language': p.suffix.lower(),
            'syntax_ok': None,
            'imports': [],
            'dangerous': [],
            'secrets': [],
        }
        if p.suffix.lower() in {'.py', '.pyw'}:
            try:
                tree = ast.parse(source, filename=str(p))
                result['syntax_ok'] = True
                imports: List[str] = []
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        imports.extend(x.name for x in node.names)
                    elif isinstance(node, ast.ImportFrom) and node.module:
                        imports.append(node.module)
                result['imports'] = sorted(set(imports))
            except SyntaxError as exc:
                result['syntax_ok'] = False
                result['syntax_error'] = f'line {exc.lineno}: {exc.msg}'
        for match in self.DANGEROUS.finditer(source):
            result['dangerous'].append(match.group(0)[:100])
        secret_re = re.compile(r'(?i)(AIza[0-9A-Za-z_-]{20,}|(?:sk|gsk|xox)[_-][A-Za-z0-9_-]{16,}|\b\d{8,}:AA[A-Za-z0-9_-]{20,})')
        result['secrets'] = ['literal credential-like token detected'] if secret_re.search(source) else []
        return result

    def snapshot(self, rel_paths: Sequence[str]) -> Path:
        stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
        target = BACKUP_DIR / stamp
        target.mkdir(parents=True, exist_ok=True)
        manifest = []
        for rel in rel_paths:
            safe = self.rel(rel)
            if not self.allowed(safe):
                raise ValueError(f'Cannot snapshot protected path: {safe}')
            src = self.root / safe
            if not src.exists():
                continue
            dst = target / safe
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
            manifest.append(safe)
        (target / 'manifest.json').write_text(json.dumps({'files': manifest}, indent=2), encoding='utf-8')
        return target

    def rollback(self, snapshot_dir: Path) -> None:
        manifest_path = snapshot_dir / 'manifest.json'
        data = json.loads(manifest_path.read_text(encoding='utf-8'))
        for rel in data.get('files', []):
            src = snapshot_dir / rel
            dst = self.root / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)


WORKSPACE = SafeWorkspace(WORKSPACE_DIR)


class GeminiBrain:
    def __init__(self, api_key: str, model: str = GEMINI_MODEL):
        self.api_key = api_key
        self.model = model
        self.lock = asyncio.Semaphore(4)

    def _thinking_for(self, text: str) -> str:
        score = len(text) + text.count(' and ') * 25 + text.count(' aur ') * 25
        action_words = sum(text.casefold().count(x) for x in [
            'mute', 'ban', 'kick', 'promote', 'rename', 'forward', 'reply', 'wait', 'send',
            'join', 'leave', 'change', 'edit', 'fix', 'code', 'project', 'multiple',
        ])
        complexity = score + action_words * 35
        if complexity < 90:
            return GEMINI_THINKING_SIMPLE
        if complexity < 240:
            return GEMINI_THINKING_STANDARD
        return GEMINI_THINKING_COMPLEX

    def _payload(self, system: str, user: str, think: str) -> Dict[str, Any]:
        return {
            'systemInstruction': {'parts': [{'text': system}]},
            'contents': [{'role': 'user', 'parts': [{'text': user}]}],
            'generationConfig': {
                'temperature': 0.2,
                'maxOutputTokens': GEMINI_MAX_OUTPUT,
                'thinkingConfig': {'thinkingLevel': think},
            },
        }

    async def complete(self, system: str, user: str, think: Optional[str] = None) -> str:
        if not self.api_key:
            raise RuntimeError('GEMINI_API_KEY not configured')
        level = think or self._thinking_for(user)
        payload = self._payload(system, user, level)
        body = json.dumps(payload).encode('utf-8')
        req = urllib.request.Request(
            GEMINI_API_URL.format(model=urllib.parse.quote(self.model, safe='')),
            data=body,
            method='POST',
            headers={'Content-Type': 'application/json', 'x-goog-api-key': self.api_key},
        )
        async with self.lock:
            def _request() -> str:
                with urllib.request.urlopen(req, timeout=GEMINI_TIMEOUT) as response:
                    raw = response.read().decode('utf-8', 'replace')
                data = json.loads(raw)
                pieces: List[str] = []
                for cand in data.get('candidates', []):
                    for part in cand.get('content', {}).get('parts', []):
                        if isinstance(part.get('text'), str):
                            pieces.append(part['text'])
                text = ''.join(pieces).strip()
                if not text:
                    raise RuntimeError('Gemini returned no text')
                return text
            return await asyncio.to_thread(_request)

    async def json(self, system: str, user: str, think: Optional[str] = None) -> Dict[str, Any]:
        raw = await self.complete(system, user, think=think)
        text = raw.strip()
        if text.startswith('```'):
            text = re.sub(r'^```(?:json)?\s*', '', text, flags=re.I)
            text = re.sub(r'\s*```$', '', text)
        start = text.find('{')
        end = text.rfind('}')
        if start < 0 or end <= start:
            raise ValueError('No JSON object in model response')
        return json.loads(text[start:end + 1])


