ToolFunc = Callable[[ToolContext, Dict[str, Any]], Awaitable[ToolResult]]


@dataclass(slots=True)
class AgentTool:
    name: str
    description: str
    func: ToolFunc
    risk: Literal['read', 'write', 'moderate', 'code'] = 'read'
    aliases: Tuple[str, ...] = ()


class ToolRegistry:
    def __init__(self) -> None:
        self.tools: Dict[str, AgentTool] = {}

    def add(self, name: str, description: str, risk: str = 'read', aliases: Sequence[str] = ()) -> Callable[[ToolFunc], ToolFunc]:
        def deco(func: ToolFunc) -> ToolFunc:
            self.tools[name] = AgentTool(name, description, func, risk, tuple(aliases))
            return func
        return deco

    def get(self, name: str) -> Optional[AgentTool]:
        if name in self.tools:
            return self.tools[name]
        n = name.casefold()
        for tool in self.tools.values():
            if n == tool.name.casefold() or n in {a.casefold() for a in tool.aliases}:
                return tool
        return None

    def manifest(self) -> List[Dict[str, Any]]:
        return [
            {'name': t.name, 'description': t.description, 'risk': t.risk, 'aliases': list(t.aliases)}
            for t in self.tools.values()
        ]

    def langchain_tools(self) -> List[Any]:
        if not LANGCHAIN_READY or StructuredTool is None:
            return []
        wrappers = []
        for item in self.tools.values():
            async def call(payload: str, item=item) -> str:
                try:
                    args = json.loads(payload) if isinstance(payload, str) else dict(payload)
                except Exception:
                    args = {'value': payload}
                result = await item.func(self._ctx_placeholder, args)  # actual graph execution uses registry directly
                return result.summary
            try:
                wrappers.append(StructuredTool.from_function(
                    func=lambda payload, item=item: f'Tool {item.name} requires graph context',
                    coroutine=call,
                    name=f'lervex_{item.name}',
                    description=item.description,
                ))
            except Exception:
                continue
        return wrappers

    _ctx_placeholder = None


class Planner:
    def __init__(self, brain: GeminiBrain, registry: ToolRegistry):
        self.brain = brain
        self.registry = registry

    def _local_shortcut(self, query: str) -> Optional[AgentPlan]:
        q = query.strip()
        low = q.casefold()
        target = self._extract_target(q)
        if re.search(r'\b(mute|chup)\b', low) and target:
            return AgentPlan('mute_user', 'action', [AgentStep('s1', 'mute_user', {'target': target}, purpose='Mute requested target')], complexity='simple')
        if re.search(r'\b(unmute|bolne\s+do|unmute)\b', low) and target:
            return AgentPlan('unmute_user', 'action', [AgentStep('s1', 'unmute_user', {'target': target}, purpose='Unmute requested target')], complexity='simple')
        if re.search(r'\b(ban|block)\b', low) and target:
            return AgentPlan('ban_user', 'action', [AgentStep('s1', 'ban_user', {'target': target}, purpose='Ban requested target')], complexity='simple')
        if re.search(r'\b(kick|nikal)\b', low) and target:
            return AgentPlan('kick_user', 'action', [AgentStep('s1', 'kick_user', {'target': target}, purpose='Kick requested target')], complexity='simple')
        if re.search(r'\b(admin|promote)\b', low) and target:
            return AgentPlan('promote_admin', 'action', [AgentStep('s1', 'promote_admin', {'target': target}, purpose='Promote requested target')], complexity='simple')
        if re.search(r'\b(group|gc)\b', low) and re.search(r'\b(name|naam|title)\b', low):
            m = re.search(r'(?:name|naam|title)\s+(?:kar|karo|to|as)?\s*["\']?(.+?)["\']?$', q, re.I)
            if m:
                return AgentPlan('rename_chat', 'action', [AgentStep('s1', 'rename_chat', {'title': m.group(1).strip()}, purpose='Rename current chat')], complexity='simple')
        return None

    @staticmethod
    def _extract_target(text: str) -> str:
        m = re.search(r'(@[A-Za-z0-9_]{3,}|\b\d{5,15}\b)', text)
        if m:
            return m.group(1)
        if 'reply' in text.casefold() or 'is message' in text.casefold():
            return '${event.reply_sender}'
        return ''

    async def make(self, query: str, context: Dict[str, Any]) -> AgentPlan:
        shortcut = self._local_shortcut(query)
        if shortcut:
            return shortcut
        tool_text = json.dumps(self.registry.manifest(), ensure_ascii=False)
        system = (
            'You are 𝘭𝘦𝘳𝘷𝘦𝘹, a Telegram account agent. Convert Hinglish, Hindi-English, slang, typo-heavy natural language into a safe execution plan. '
            'Return JSON only. Never invent tools. Use at most 8 steps. Each step is {id,tool,args,depends_on,purpose,critical}. '
            'For independent read actions you may omit dependencies. For a send-and-wait workflow prefer the single specialized tool send_and_forward_reply. '
            'Use chat-local context placeholders only when documented. Never create bulk spam, raid, harassment, credential theft, or arbitrary shell execution plans. '
            'For risky moderation, rely on Telegram permissions and report real errors. '
            'Available tools: ' + tool_text
        )
        user = json.dumps({'query': query, 'context': context}, ensure_ascii=False)
        raw = await self.brain.json(system, user)
        steps: List[AgentStep] = []
        for idx, item in enumerate(raw.get('steps', [])[:MAX_PLAN_STEPS], 1):
            tool = str(item.get('tool', '')).strip()
            if not tool or not self.registry.get(tool):
                continue
            args = item.get('args') if isinstance(item.get('args'), dict) else {}
            deps = item.get('depends_on') if isinstance(item.get('depends_on'), list) else []
            steps.append(AgentStep(
                id=str(item.get('id') or f's{idx}'),
                tool=tool,
                args=args,
                depends_on=[str(x) for x in deps],
                purpose=str(item.get('purpose') or ''),
                critical=bool(item.get('critical', True)),
            ))
        if not steps:
            steps = [AgentStep('s1', 'chat', {'text': query}, purpose='Natural-language response', critical=False)]
        complexity = str(raw.get('complexity', 'standard')).lower()
        if complexity not in {'simple', 'standard', 'complex'}:
            complexity = 'standard'
        return AgentPlan(str(raw.get('intent', 'chat')), str(raw.get('answer_mode', 'action')), steps, list(raw.get('notes', [])), complexity)  # type: ignore[arg-type]


class Verifier:
    def __init__(self, app: 'LervexApp'):
        self.app = app

    async def verify(self, step: AgentStep, result: ToolResult, ctx: ToolContext) -> Dict[str, Any]:
        if not result.ok:
            return {'ok': False, 'reason': result.error or result.summary}
        tool = step.tool
        try:
            if tool == 'rename_chat':
                chat = await self.app.client.get_entity(ctx.chat_id)
                title = getattr(chat, 'title', '')
                expected = str(step.args.get('title', '')).strip()
                return {'ok': bool(title == expected), 'observed': title, 'expected': expected}
            if tool in {'mute_user', 'unmute_user'}:
                entity = await self.app.resolver.resolve(step.args.get('target'), ctx.event)
                p = await self.app.client.get_permissions(ctx.chat_id, entity)
                restricted = bool(getattr(p, 'send_messages', None) is False)
                return {'ok': restricted if tool == 'mute_user' else not restricted, 'observed_restricted': restricted}
            if tool in {'pin_message'}:
                return {'ok': True, 'verified_by_api': True}
            return {'ok': True, 'verified_by_action': True}
        except Exception as exc:
            return {'ok': False, 'reason': str(exc)[:300]}


class LervexApp:
    def __init__(self, config: RuntimeConfig, client: Any):
        self.config = config
        self.client = client
        self.permissions = PermissionGate(client, config.owner_id)
        self.resolver = EntityResolver(client)
        self.tools = ToolRegistry()
        self.brain = GeminiBrain(config.gemini_key, config.gemini_model)
        self.planner = Planner(self.brain, self.tools)
        self.verifier = Verifier(self)
        self.workspace = WORKSPACE
        self.started_at = time.time()
        self.owner_name = 'Nikku'
        self.autopilot = False
        self.incoming_filter_tasks: Dict[int, str] = {}
        self.reaction_rules: Dict[int, str] = {}
        self.afk: Dict[str, Any] = {'active': False, 'reason': ''}
        self.awaits: Dict[str, asyncio.Task] = {}
        self._register_tools()
        self.graph = self._build_graph() if LANGGRAPH_READY else None

    def _build_graph(self) -> Any:
        if not LANGGRAPH_READY or StateGraph is None:
            return None
        try:
            g = StateGraph(GraphState)
            g.add_node('capture', self._graph_capture)
            g.add_node('plan', self._graph_plan)
            g.add_node('execute', self._graph_execute)
            g.add_node('verify', self._graph_verify)
            g.add_node('respond', self._graph_respond)
            g.add_node('remember', self._graph_remember)
            g.set_entry_point('capture')
            g.add_edge('capture', 'plan')
            g.add_edge('plan', 'execute')
            g.add_edge('execute', 'verify')
            g.add_edge('verify', 'respond')
            g.add_edge('respond', 'remember')
            g.add_edge('remember', END)
            return g.compile()
        except Exception:
            return None

    async def _graph_capture(self, state: GraphState) -> Dict[str, Any]:
        state['trace'] = ['capture']
        return state

    async def _graph_plan(self, state: GraphState) -> Dict[str, Any]:
        plan = await self.planner.make(state['query'], state.get('context', {}))
        state['plan'] = self.plan_to_dict(plan)
        state.setdefault('trace', []).append('plan')
        return state

    async def _graph_execute(self, state: GraphState) -> Dict[str, Any]:
        event = state['context']['event']
        ctx = ToolContext(self, event)
        plan = self.plan_from_dict(state['plan'])
        state['results'] = [r.compact() for r in await self.execute_plan(plan, ctx)]
        state.setdefault('trace', []).append('execute')
        return state

    async def _graph_verify(self, state: GraphState) -> Dict[str, Any]:
        state['verification'] = {'ok': all(bool(x.get('ok')) for x in state.get('results', [])), 'count': len(state.get('results', []))}
        state.setdefault('trace', []).append('verify')
        return state

    async def _graph_respond(self, state: GraphState) -> Dict[str, Any]:
        state['response'] = self.render_results(state.get('results', []), state.get('verification', {}))
        state.setdefault('trace', []).append('respond')
        return state

    async def _graph_remember(self, state: GraphState) -> Dict[str, Any]:
        await self.remember(state['query'], state.get('plan', {}), state.get('results', []), state['chat_id'])
        state.setdefault('trace', []).append('remember')
        return state

    @staticmethod
    def plan_to_dict(plan: AgentPlan) -> Dict[str, Any]:
        return {
            'intent': plan.intent,
            'answer_mode': plan.answer_mode,
            'complexity': plan.complexity,
            'notes': plan.notes,
            'steps': [asdict(s) for s in plan.steps],
        }

    @staticmethod
    def plan_from_dict(data: Dict[str, Any]) -> AgentPlan:
        return AgentPlan(
            intent=data.get('intent', 'chat'),
            answer_mode=data.get('answer_mode', 'action'),
            complexity=data.get('complexity', 'standard'),
            notes=list(data.get('notes', [])),
            steps=[AgentStep(**x) for x in data.get('steps', [])],
        )

    async def run_agent(self, event: Any, query: str) -> str:
        if not await self.permissions.is_controller(event.sender_id):
            return f'{AGENT_FAIL} owner/control access required.'
        ctx = {
            'event': event,
            'chat_id': event.chat_id,
            'reply_message_id': getattr(getattr(event, 'message', None), 'reply_to_msg_id', None),
            'sender_id': event.sender_id,
            'wake_word': WAKE_WORD,
            'active_tasks': TASKS.snapshot(),
            'current_time': datetime.now(timezone.utc).isoformat(),
        }
        if self.graph is not None:
            state = await self.graph.ainvoke({'query': query, 'chat_id': int(event.chat_id or 0), 'sender_id': int(event.sender_id or 0), 'context': ctx})
            return state.get('response') or self.render_results(state.get('results', []), state.get('verification', {}))
        plan = await self.planner.make(query, ctx)
        progress = await event.respond(AGENT_ACK)
        results = await self.execute_plan(plan, ToolContext(self, event))
        return self.render_results([x.compact() for x in results], {'ok': all(x.ok for x in results)})

    async def execute_plan(self, plan: AgentPlan, ctx: ToolContext) -> List[ToolResult]:
        results: List[ToolResult] = []
        done: Dict[str, ToolResult] = {}
        pending = list(plan.steps)
        while pending:
            ready = [s for s in pending if all(dep in done for dep in s.depends_on)]
            if not ready:
                ready = [pending[0]]
            async def run_step(step: AgentStep) -> ToolResult:
                tool = self.tools.get(step.tool)
                if not tool:
                    return ToolResult(False, step.tool, 'Unknown tool', error='Tool not registered')
                args = self.interpolate(step.args, done, ctx)
                started = time.monotonic()
                try:
                    result = await tool.func(ctx, args)
                    result.duration_ms = int((time.monotonic() - started) * 1000)
                    if result.ok:
                        verification = await self.verifier.verify(step, result, ctx)
                        result.verified = bool(verification.get('ok', True))
                        if not result.verified and step.critical:
                            result.ok = False
                            result.error = verification.get('reason', 'Post-action verification failed')
                    return result
                except FloodWaitError as exc:
                    await asyncio.sleep(float(getattr(exc, 'seconds', 1)) + 0.25)
                    try:
                        result = await tool.func(ctx, args)
                        result.duration_ms = int((time.monotonic() - started) * 1000)
                        result.verified = result.ok
                        return result
                    except Exception as retry_exc:
                        return ToolResult(False, step.tool, 'Retry failed', error=str(retry_exc)[:300])
                except Exception as exc:
                    return ToolResult(False, step.tool, 'Execution failed', error=f'{type(exc).__name__}: {exc}'[:500])
            batch = await asyncio.gather(*(run_step(s) for s in ready))
            for step, result in zip(ready, batch):
                results.append(result)
                done[step.id] = result
                if not result.ok and step.critical:
                    repaired = await self.try_repair(step, result, plan, ctx)
                    if repaired is not None:
                        results.extend(repaired)
                        done[step.id] = repaired[-1]
                    else:
                        for s in pending:
                            if step.id in s.depends_on:
                                s.critical = False
            pending = [s for s in pending if s.id not in {x.id for x in ready}]
        return results

    async def try_repair(self, step: AgentStep, failure: ToolResult, plan: AgentPlan, ctx: ToolContext) -> Optional[List[ToolResult]]:
        if step.tool in {'mute_user', 'unmute_user', 'ban_user', 'kick_user', 'promote_admin', 'demote_admin'}:
            return None
        repair_system = (
            'You are 𝘭𝘦𝘳𝘷𝘦𝘹 repair planner. Return JSON {"tool":string,"args":object,"why":string} or {"tool":"none"}. '
            'Only select a tool already available. Do not invent shell commands. Fix transient resolution/format mistakes only.'
        )
        repair_user = json.dumps({'failed_step': asdict(step), 'failure': failure.compact(), 'tools': self.tools.manifest()}, ensure_ascii=False)
        try:
            data = await self.brain.json(repair_system, repair_user, think=GEMINI_THINKING_STANDARD)
            name = str(data.get('tool', 'none'))
            if name == 'none' or not self.tools.get(name):
                return None
            repaired_step = AgentStep(step.id + '_repair', name, data.get('args', {}), purpose='Bounded automatic repair', critical=step.critical)
            tool = self.tools.get(name)
            result = await tool.func(ctx, self.interpolate(repaired_step.args, {}, ctx))
            result.summary = f'Repair: {result.summary}'
            result.verified = result.ok
            return [result]
        except Exception as exc:
            log.debug('repair failed: %s', exc)
            return None

    @staticmethod
    def interpolate(value: Any, done: Dict[str, ToolResult], ctx: ToolContext) -> Any:
        if isinstance(value, dict):
            return {k: LervexApp.interpolate(v, done, ctx) for k, v in value.items()}
        if isinstance(value, list):
            return [LervexApp.interpolate(v, done, ctx) for v in value]
        if not isinstance(value, str):
            return value
        if value == '${context.chat_id}':
            return ctx.chat_id
        if value == '${context.reply_message_id}':
            return getattr(getattr(ctx.event, 'message', None), 'reply_to_msg_id', None)
        m = re.fullmatch(r'\$\{result\.([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]+)\}', value)
        if m:
            item = done.get(m.group(1))
            if item:
                return item.data.get(m.group(2))
        return value

    async def remember(self, query: str, plan: Dict[str, Any], results: List[Dict[str, Any]], chat_id: int) -> None:
        mem = STATE.value.setdefault('memory', [])
        mem.append({
            'time': datetime.now(timezone.utc).isoformat(),
            'chat_id': chat_id,
            'query': query[:1000],
            'intent': plan.get('intent'),
            'tools': [x.get('tool') for x in results],
            'ok': all(bool(x.get('ok')) for x in results),
        })
        STATE.value['memory'] = mem[-300:]
        await STATE.save()

    @staticmethod
    def render_results(results: List[Dict[str, Any]], verification: Dict[str, Any]) -> str:
        if not results:
            return f'{AGENT_FAIL} no execution result.'
        lines = []
        all_ok = True
        for item in results:
            ok = bool(item.get('ok'))
            all_ok = all_ok and ok
            icon = '✅' if ok else '❌'
            summary = item.get('summary') or item.get('error') or 'done'
            lines.append(f'{icon} {summary}')
        icon = '✅' if all_ok else '⚠️'
        return APP_NAME + f' {icon}\n' + '\n'.join(lines[:12])

    def _register_tools(self) -> None:
        add = self.tools.add

        @add('chat', 'Reply naturally in Hinglish with context-aware short answers', 'read', aliases=('talk', 'reply'))
        async def chat(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            text = str(args.get('text') or '')
            system = (
                'You are 𝘭𝘦𝘳𝘷𝘦𝘹, owner-controlled Telegram AI. Reply in natural Hinglish, concise, warm, clear. '
                'Never claim an action happened unless a tool result proves it. Use emojis sparingly.'
            )
            reply = await self.brain.complete(system, text)
            return ToolResult(True, 'chat', reply, {'text': reply})

        @add('status', 'Show uptime, agent state, dependencies and task counts', 'read', aliases=('alive', 'ping', 'stats'))
        async def status(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            up = int(time.time() - self.started_at)
            deps = self.dependencies()
            text = f'UP {up}s | Graph={bool(self.graph)} | LangChain={LANGCHAIN_READY} | Gemini={bool(self.config.gemini_key)} | tasks={len(TASKS.tasks)}'
            return ToolResult(True, 'status', text, {'uptime': up, 'deps': deps, 'tasks': TASKS.snapshot()})

        @add('read_messages', 'Read recent messages from a chat', 'read', aliases=('history', 'recent'))
        async def read_messages(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            chat = args.get('chat_id', ctx.chat_id)
            limit = max(1, min(50, int(args.get('limit', 10))))
            messages = []
            async for m in self.client.iter_messages(chat, limit=limit):
                messages.append({'id': m.id, 'sender_id': m.sender_id, 'text': (m.text or '')[:1500], 'date': str(m.date)})
            return ToolResult(True, 'read_messages', f'Read {len(messages)} messages', {'messages': messages, 'chat_id': chat})

        @add('send_message', 'Send one message to one target', 'moderate', aliases=('dm', 'message', 'send'))
        async def send_message(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            target = args.get('target') or args.get('chat_id')
            text = str(args.get('text') or args.get('message') or '')
            if not text:
                raise ValueError('Message text is empty')
            entity = await self.resolver.resolve(target, ctx.event)
            await SEND_GATE.wait(int(getattr(entity, 'id', ctx.chat_id)))
            sent = await self.client.send_message(entity, text)
            return ToolResult(True, 'send_message', f'Sent message to {getattr(entity, "id", entity)}', {'chat_id': int(getattr(entity, 'id', 0)), 'message_id': sent.id, 'text': text})

        @add('send_and_wait', 'Send one message to one target, then wait for one incoming response', 'moderate', aliases=('ask_and_wait', 'query_user'))
        async def send_and_wait(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            target = args.get('target') or args.get('chat_id')
            text = str(args.get('text') or '')
            timeout = max(2.0, min(90.0, float(args.get('timeout', 20))))
            entity = await self.resolver.resolve(target, ctx.event)
            sent = await self.client.send_message(entity, text)
            my_id = await self.get_me_id()
            deadline = time.monotonic() + timeout
            response = None
            while time.monotonic() < deadline:
                msgs = await self.client.get_messages(entity, limit=20)
                for msg in msgs:
                    if msg.id > sent.id and msg.sender_id and int(msg.sender_id) != my_id:
                        response = msg
                        break
                if response:
                    break
                await asyncio.sleep(0.8)
            if response is None:
                return ToolResult(False, 'send_and_wait', 'No response before timeout', error=f'timeout {timeout}s', data={'source_chat_id': int(getattr(entity, 'id', 0)), 'sent_message_id': sent.id})
            return ToolResult(True, 'send_and_wait', 'Response received', {
                'source_chat_id': int(getattr(entity, 'id', 0)),
                'sent_message_id': sent.id,
                'reply_id': response.id,
                'reply_text': response.text or '',
            })

        @add('send_and_forward_reply', 'Send one message to a target, wait for one response, forward that response to the current control chat', 'moderate', aliases=('ask_forward',))
        async def send_and_forward_reply(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            base = await send_and_wait(ctx, args)
            if not base.ok:
                return base
            src = base.data['source_chat_id']
            reply_id = base.data['reply_id']
            forwarded = await self.client.forward_messages(ctx.control_chat_id, reply_id, from_peer=src)
            f_id = getattr(forwarded, 'id', forwarded[0].id if isinstance(forwarded, list) and forwarded else None)
            return ToolResult(True, 'send_and_forward_reply', 'Response forwarded to control chat', {
                **base.data, 'forwarded_message_id': f_id, 'control_chat_id': ctx.control_chat_id
            })

        @add('forward_message', 'Forward one specific message from one chat to another', 'moderate', aliases=('forward', 'fw'))
        async def forward_message(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            source_chat = args.get('source_chat_id') or ctx.chat_id
            target = args.get('target') or args.get('target_chat_id') or ctx.chat_id
            msg_id = int(args.get('message_id') or 0)
            if not msg_id:
                raise ValueError('message_id required')
            sent = await self.client.forward_messages(target, msg_id, from_peer=source_chat)
            return ToolResult(True, 'forward_message', 'Message forwarded', {'message_id': msg_id, 'target_chat_id': int(getattr(sent, 'chat_id', target) or 0)})

        @add('join_chat', 'Join a public username or invite link', 'moderate', aliases=('join', 'joi'))
        async def join_chat(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            raw = str(args.get('link') or args.get('target') or '')
            if not raw:
                raise ValueError('Link or username required')
            if raw.startswith('t.me/'):
                raw = 'https://' + raw
            if 'joinchat/' in raw or 't.me/+' in raw:
                token = raw.rstrip('/').split('/')[-1].lstrip('+')
                await self.client(functions.messages.ImportChatInviteRequest(token))
            else:
                username = raw.split('t.me/')[-1].split('?')[0].lstrip('@').strip('/')
                if not username:
                    raise ValueError('Invalid public username/link')
                await self.client(functions.channels.JoinChannelRequest(username))
            return ToolResult(True, 'join_chat', 'Joined requested chat', {'target': raw})

        @add('leave_chat', 'Leave current or specified chat', 'moderate', aliases=('leave', 'exit'))
        async def leave_chat(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            target = args.get('target') or args.get('chat_id') or ctx.chat_id
            await self.client.delete_dialog(target)
            return ToolResult(True, 'leave_chat', f'Left {target}', {'chat_id': int(target) if str(target).lstrip('-').isdigit() else None})

        @add('rename_chat', 'Rename a group or channel', 'moderate', aliases=('rename_group', 'group_name', 'title'))
        async def rename_chat(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            title = str(args.get('title') or args.get('name') or '').strip()
            if not title:
                raise ValueError('New title required')
            target = args.get('chat_id') or ctx.chat_id
            entity = await self.client.get_entity(target)
            if getattr(entity, 'megagroup', False) or getattr(entity, 'broadcast', False):
                await self.client(functions.channels.EditTitleRequest(channel=entity, title=title))
            else:
                await self.client(functions.messages.EditChatTitleRequest(chat_id=entity, title=title))
            return ToolResult(True, 'rename_chat', f'Chat renamed to {title}', {'title': title})

        @add('set_description', 'Set group or channel description', 'moderate', aliases=('description', 'bio_chat'))
        async def set_description(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            text = str(args.get('text') or args.get('description') or '')
            entity = await self.client.get_entity(args.get('chat_id') or ctx.chat_id)
            await self.client(functions.channels.EditAboutRequest(channel=entity, about=text))
            return ToolResult(True, 'set_description', 'Chat description updated', {'text': text})

        async def _moderation_target(ctx: ToolContext, args: Dict[str, Any]) -> Any:
            return await self.resolver.resolve(args.get('target'), ctx.event)

        @add('mute_user', 'Restrict a target from sending messages in the current chat', 'moderate', aliases=('mute', 'chup', 'silence'))
        async def mute_user(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            entity = await _moderation_target(ctx, args)
            until = args.get('until_date')
            rights = types.ChatBannedRights(send_messages=True, until_date=until)
            await self.client(functions.channels.EditBannedRequest(channel=ctx.chat_id, participant=entity, banned_rights=rights))
            return ToolResult(True, 'mute_user', f'Muted {getattr(entity, "id", entity)}', {'target_id': int(getattr(entity, 'id', 0))})

        @add('unmute_user', 'Remove send-message restriction from a target', 'moderate', aliases=('unmute', 'bolne_do'))
        async def unmute_user(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            entity = await _moderation_target(ctx, args)
            await self.client(functions.channels.EditBannedRequest(channel=ctx.chat_id, participant=entity, banned_rights=types.ChatBannedRights()))
            return ToolResult(True, 'unmute_user', f'Unmuted {getattr(entity, "id", entity)}', {'target_id': int(getattr(entity, 'id', 0))})

        @add('ban_user', 'Ban a target from the current chat', 'moderate', aliases=('ban', 'block'))
        async def ban_user(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            entity = await _moderation_target(ctx, args)
            await self.client(functions.channels.EditBannedRequest(channel=ctx.chat_id, participant=entity, banned_rights=types.ChatBannedRights(view_messages=True)))
            return ToolResult(True, 'ban_user', f'Banned {getattr(entity, "id", entity)}', {'target_id': int(getattr(entity, 'id', 0))})

        @add('unban_user', 'Unban a target', 'moderate', aliases=('unban', 'unblock'))
        async def unban_user(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            entity = await _moderation_target(ctx, args)
            await self.client(functions.channels.EditBannedRequest(channel=ctx.chat_id, participant=entity, banned_rights=types.ChatBannedRights()))
            return ToolResult(True, 'unban_user', f'Unbanned {getattr(entity, "id", entity)}', {'target_id': int(getattr(entity, 'id', 0))})

        @add('kick_user', 'Remove a target from a modern group by temporary ban then release', 'moderate', aliases=('kick', 'remove', 'nikal'))
        async def kick_user(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            entity = await _moderation_target(ctx, args)
            await self.client(functions.channels.EditBannedRequest(channel=ctx.chat_id, participant=entity, banned_rights=types.ChatBannedRights(view_messages=True)))
