        @add('delete_message', 'Delete one message or a bounded list in current chat', 'moderate', aliases=('del', 'delete'))
        async def delete_message(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            ids = args.get('message_ids') or ([args.get('message_id')] if args.get('message_id') else [])
            ids = [int(x) for x in ids if str(x).isdigit()][:100]
            if not ids and getattr(ctx.event, 'message', None):
                ids = [ctx.event.message.id]
            if not ids:
                raise ValueError('message_id required')
            await self.client.delete_messages(ctx.chat_id, ids)
            return ToolResult(True, 'delete_message', f'Deleted {len(ids)} message(s)', {'message_ids': ids})

        @add('purge_reply_chain', 'Delete a bounded range ending at the replied message', 'moderate', aliases=('purge', 'clear'))
        async def purge_reply_chain(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            count = max(1, min(100, int(args.get('count', 20))))
            anchor = int(args.get('message_id') or getattr(getattr(ctx.event, 'message', None), 'reply_to_msg_id', 0) or 0)
            if not anchor:
                raise ValueError('Reply to an anchor message')
            start = max(1, anchor - count + 1)
            await self.client.delete_messages(ctx.chat_id, list(range(start, anchor + 1)))
            return ToolResult(True, 'purge_reply_chain', f'Deleted up to {count} messages', {'start': start, 'end': anchor})

