        @add('set_sudo', 'Add or remove a trusted controller id', 'moderate', aliases=('sudo', 'delsudo'))
        async def set_sudo(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            uid = int(args.get('user_id') or (await self.resolver.resolve(args.get('target'), ctx.event)).id)
            enabled = bool(args.get('enabled', True))
            sudo = {int(x) for x in STATE.value.setdefault('sudo', [])}
            if enabled:
                sudo.add(uid)
            else:
                sudo.discard(uid)
            STATE.value['sudo'] = sorted(sudo)
            await STATE.save()
            return ToolResult(True, 'set_sudo', f'Sudo {"added" if enabled else "removed"}: {uid}')

