        @add('remind', 'Schedule a reminder in seconds', 'moderate', aliases=('reminder', 'remindme'))
        async def remind(ctx: ToolContext, args: Dict[str, Any]) -> ToolResult:
            seconds = max(1, min(7 * 86400, int(args.get('seconds', 60))))
            text = str(args.get('text') or 'Reminder')[:500]
            key = f'remind:{ctx.chat_id}:{int(time.time()*1000)}'
            async def job() -> None:
                await asyncio.sleep(seconds)
                await self.client.send_message(ctx.chat_id, f'⏰ {APP_NAME} {text}')
            await TASKS.add(key, job(), kind='reminder', chat_id=ctx.chat_id, text=text)
            return ToolResult(True, 'remind', f'Reminder scheduled in {seconds}s', {'task': key})

