# ----- event wiring -----

def build_client(config: RuntimeConfig) -> Any:
    if not TELETHON_READY:
        raise RuntimeError(f'Telethon unavailable: {TELETHON_IMPORT_ERROR}')
    return TelegramClient(StringSession(config.session), config.api_id, config.api_hash, auto_reconnect=True, connection_retries=999, request_retries=5, retry_delay=0.5)


def attach_handlers(app: LervexApp) -> None:
    @app.client.on(events.NewMessage(incoming=True))
    async def on_incoming(event: Any) -> None:
        if await app.wake_handler(event):
            return
        if await app.command_handler(event):
            return
        await app.passive_message(event)

    @app.client.on(events.NewMessage(outgoing=True))
    async def on_outgoing(event: Any) -> None:
        # Outgoing messages are still processed for dot commands emitted by helper accounts.
        if await app.command_handler(event):
            return


async def start_app() -> None:
    config = RuntimeConfig.from_env(strict=True)
    client = build_client(config)
    app = LervexApp(config, client)
    attach_handlers(app)
    await client.start()
    me = await client.get_me()
    log.info('%s online as %s (%s)', APP_NAME, getattr(me, 'username', None) or getattr(me, 'first_name', 'account'), me.id)
    await client.run_until_disconnected()


def self_test() -> int:
    checks = []
    checks.append(('python', sys.version.split()[0]))
    checks.append(('telethon', TELETHON_READY))
    checks.append(('langchain', LANGCHAIN_READY))
    checks.append(('langgraph', LANGGRAPH_READY))
    checks.append(('pydantic', PYDANTIC_READY))
    checks.append(('safe_math', safe_math('2 + 3 * 4') == 14))
    checks.append(('wake_regex', bool(WAKE_PATTERN.search('Lervex, mute @x'))))
    checks.append(('workspace_root', WORKSPACE.root.exists()))
    for name, value in checks:
        print(f'[{"OK" if value else "WARN"}] {name}: {value}')
    ast.parse(Path(__file__).read_text(encoding='utf-8'))
    print(f'{APP_NAME} self-test: PASS')
    return 0


if __name__ == '__main__':
    if os.getenv('LERVEX_SELF_TEST') == '1':
        raise SystemExit(self_test())
    asyncio.run(start_app())


