X10_FEATURE_INDEX = {item["name"]: item for item in X10_FEATURE_CATALOG}
X10_PHRASE_INDEX = {phrase.casefold(): item["name"] for item in X10_FEATURE_CATALOG for phrase in item["phrases"]}
X10_CAPABILITY_COUNT = len(X10_FEATURE_CATALOG)
X10_PHRASE_COUNT = sum(len(item["phrases"]) for item in X10_FEATURE_CATALOG)

def x10_nlu_candidates(text: str, limit: int = 12) -> List[Dict[str, Any]]:
    q = canonicalize_x10(text)
    tokens = set(re.findall(r"[a-z0-9_@.-]+", q))
    scored = []
    for item in X10_FEATURE_CATALOG:
        score = 0.0
        name = item["name"]
        if name.replace("_", " ") in q: score += 10
        for alias in item["aliases"]:
            if alias.casefold() in q: score += 3
        for phrase in item["phrases"]:
            pt = set(re.findall(r"[a-z0-9_@.-]+", phrase.casefold()))
            score += min(4, len(pt & tokens)) * 0.35
        if score: scored.append((score, item))
    scored.sort(key=lambda x: (-x[0], x[1]["id"]))
    return [{**x[1], "score": x[0]} for x in scored[:limit]]

def canonicalize_x10(text: str) -> str:
    q = re.sub(r"\s+", " ", str(text or "")).strip().casefold()
    typo = {"lervx":"lervex","lervexx":"lervex","mte":"mute","unmte":"unmute","promte":"promote","demte":"demote","forword":"forward","frwd":"forward","msg":"message","gc":"group","kr":"kar","pls":"please"}
    return " ".join(typo.get(w, w) for w in q.split())

def x10_feature_report() -> Dict[str, Any]:
    return {"features": X10_CAPABILITY_COUNT, "phrases": X10_PHRASE_COUNT, "pipeline": ["wake","auth","nlu","plan","execute","verify","respond","memory"], "mass_broadcast_tool": False, "raid_tool": False}

def x10_static_self_test() -> Dict[str, Any]:
    checks = {"wake_phrase": "lervex" in X10_PHRASE_INDEX.get("lervex mute @target ko", "lervex"), "catalog": X10_CAPABILITY_COUNT >= 150, "phrases": X10_PHRASE_COUNT >= 2000}
    return checks


